const msg=$input.first().json.message||{};
const text=(msg.text||'').trim();
const chatId=(msg.chat&&msg.chat.id)||'';
// Heuristic: long text or 'script:' prefix => user supplied a script
const lower=text.toLowerCase();
const isScript = lower.startsWith('script:') || lower.startsWith('/script') || text.length>320;
const sys='You are the request router for an on-demand short-video bot. Extract structured JSON. Respond JSON only.';
const usr=`User message:\n\"${text}\"\n\nReturn JSON: {\n \"mode\": \"topic | script\",  (\"script\" if the user pasted an actual script/voiceover text, else \"topic\")\n \"topic\": \"the topic if mode=topic, else short summary\",\n \"script\": \"the full provided script if mode=script, else empty\",\n \"platform\": \"youtube | tiktok | both | empty\"\n}`;
return [{ json:{ chatId, rawText:text, hint:isScript?'script':'topic', requestBody:{ model: ($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.1, max_tokens:600 } } }];

const prev=$('🧠 Build Intent Prompt').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const m=(($input.first().json.choices||[{}])[0].message||{}).content||'';const mm=m.match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const mode=(o.mode|| prev.hint || 'topic');
return [{ json:{ chatId:prev.chatId, mode, topic:o.topic||prev.rawText, script:o.script||'', platform:(o.platform||'youtube').trim()||'youtube' } }];

const r=$('📋 Parse Request').first().json;
const scenes=$vars.VIDEO_SCENES||4;
const sys='You are an elite short-form scriptwriter and director. You write high-retention vertical video scripts. For each scene you provide spoken narration, a punchy on-screen caption (<=6 words), an IMAGE prompt (a vivid still frame to generate), and a MOTION prompt (how the camera/subject should move when the still is animated into video). Respond with strict JSON only.';
let usr;
if(r.mode==='script'){ usr=`The creator provided this SCRIPT. Keep their message and voice, but split it into ${scenes} scenes and add visuals. Do not rewrite the meaning.\nSCRIPT:\n\"${r.script||r.topic}\"\n\nReturn JSON: {\"hook\":\"first spoken line\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"...\",\"image_prompt\":\"vivid still-frame description, cinematic, vertical 9:16, no text\",\"motion_prompt\":\"how it should animate, e.g. slow push-in\"}],\"cta\":\"final spoken line\"}`; }
else { usr=`Write a high-retention ${scenes}-scene vertical short about: \"${r.topic}\".\nStructure: pattern-interrupt HOOK (0-3s) -> escalating value beats -> payoff -> crisp CTA. Total spoken 90-140 words, conversational and punchy.\nReturn JSON: {\"hook\":\"first spoken line\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"...\",\"image_prompt\":\"vivid still-frame description, cinematic, vertical 9:16, no text\",\"motion_prompt\":\"how it should animate, e.g. slow push-in\"}],\"cta\":\"final spoken line\"}`; }
return [{ json:{ ...r, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.85, max_tokens:1500 } } }];

const r=$('✍️ Agent: Script Writer').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const m=(($input.first().json.choices||[{}])[0].message||{}).content||'';const mm=m.match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const draft={ hook:o.hook||'', cta:o.cta||'', scenes:(o.scenes||[]).map((s,i)=>({ idx:i, narration:s.narration||'', on_screen_text:s.on_screen_text||'', image_prompt:s.image_prompt||r.topic, motion_prompt:s.motion_prompt||'slow cinematic push-in' })) };
const sys='You are a brutally effective short-form Script Doctor. You review a draft script and improve it ONLY where it helps retention: sharpen the hook, tighten wording, fix weak transitions, ensure a clear payoff and CTA. Keep the same number of scenes and the creator intent. Respond with strict JSON only.';
const usr=`Review and improve this draft. If it is already strong, make minimal edits.\nDRAFT JSON:\n${JSON.stringify(draft)}\n\nReturn JSON: {\"hook\":\"...\",\"scenes\":[{\"narration\":\"...\",\"on_screen_text\":\"...\",\"image_prompt\":\"...\",\"motion_prompt\":\"...\"}],\"cta\":\"...\",\"changes\":\"one-line summary of what you improved\"}`;
return [{ json:{ ...r, draft, requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.6, max_tokens:1500 } } }];

const r=$('🩺 Agent: Script Doctor').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const m=(($input.first().json.choices||[{}])[0].message||{}).content||'';const mm=m.match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const scenes=(o.scenes&&o.scenes.length?o.scenes:r.draft.scenes).map((s,i)=>({ idx:i, narration:s.narration||'', on_screen_text:s.on_screen_text||'', image_prompt:s.image_prompt||r.topic, motion_prompt:s.motion_prompt||'slow cinematic push-in' }));
const hook=o.hook||r.draft.hook; const cta=o.cta||r.draft.cta;
const fullScript=[hook,...scenes.map(s=>s.narration),cta].filter(Boolean).join(' ');
const sys='You are a YouTube/TikTok packaging expert. Create scroll-stopping metadata. Respond JSON only.';
const usr=`Topic: ${r.topic}\nReturn JSON: {\"title\":\"<=70 char curiosity title\",\"description\":\"2-3 sentences with keywords + CTA\",\"tags\":\"12 comma-separated keywords\",\"hashtags\":\"8 space-separated #tags\"}`;
return [{ json:{ chatId:r.chatId, platform:r.platform, topic:r.topic, hook, cta, scenes, script:fullScript, changes:o.changes||'', requestBody:{ model:($vars.OPENROUTER_LLM_MODEL||'openai/gpt-4o'), response_format:{type:'json_object'}, messages:[{role:'system',content:sys},{role:'user',content:usr}], temperature:0.7, max_tokens:500 } } }];

const r=$('🔍 Agent: SEO').first().json;
let o={};try{o=JSON.parse($input.first().json.choices[0].message.content);}catch(e){const m=(($input.first().json.choices||[{}])[0].message||{}).content||'';const mm=m.match(/\{[\s\S]*\}/);if(mm)o=JSON.parse(mm[0]);}
const master={ chatId:r.chatId, platform:r.platform, topic:r.topic, hook:r.hook, cta:r.cta, scenes:r.scenes, script:r.script, changes:r.changes, title:(o.title||r.topic||'').slice(0,95), description:o.description||'', tags:o.tags||'', hashtags:o.hashtags||'', job:'v4_'+Date.now() };
return master.scenes.map(s=>({ json:{ ...master, scene:s } }));

const item=$json;
const resp=$json;
// OpenRouter returns generated images on message.images[].image_url.url (data URL) or sometimes data[].b64_json
let b64='';
try{
  const msg=resp.choices&&resp.choices[0]&&resp.choices[0].message;
  if(msg&&msg.images&&msg.images[0]){ const u=msg.images[0].image_url?msg.images[0].image_url.url:msg.images[0].url; b64=(u||'').split(',').pop(); }
  else if(resp.data&&resp.data[0]&&resp.data[0].b64_json){ b64=resp.data[0].b64_json; }
}catch(e){}
return [{ json:{ ...$('📋 Finalize Script + Split Scenes').item.json, img_b64:b64 } }];

const base=$('🖼️ Extract Image').item.json;
const resp=$json;
let url='';try{url=resp.data.display_url||resp.data.url;}catch(e){}
const body={ model:($vars.OPENROUTER_VIDEO_MODEL||'google/veo-3.1-lite'), prompt: (base.scene.motion_prompt||'slow cinematic push-in')+', high quality, realistic motion', duration: Number($vars.VIDEO_CLIP_SECONDS||4), resolution:'720p', aspect_ratio:'9:16', generate_audio:false, frame_images:[{ type:'image_url', image_url:{ url }, frame_type:'first_frame' }] };
return [{ json:{ ...base, scene_image_url:url, videoBody:body } }];

// RUN ONCE FOR ALL ITEMS — collect every scene's video job
const preps=$('🧩 Prep Video Job').all().map(i=>i.json);
const resps=$input.all().map(i=>i.json);
const master=$('📋 Finalize Script + Split Scenes').first().json;
const jobs=resps.map((r,i)=>({ idx:i, jobId:r.id||'', status:r.status||'queued', polling_url:(r.polling_url||('/api/v1/videos/'+(r.id||''))), clip_url:'', narration:(preps[i]&&preps[i].scene.narration)||'', on_screen_text:(preps[i]&&preps[i].scene.on_screen_text)||'', scene_image_url:(preps[i]&&preps[i].scene_image_url)||'' }));
return [{ json:{ chatId:master.chatId, platform:master.platform, topic:master.topic, title:master.title, description:master.description, tags:master.tags, hashtags:master.hashtags, hook:master.hook, cta:master.cta, changes:master.changes, job:master.job, thumbnail_url:(jobs[0]&&jobs[0].scene_image_url)||'', jobs, attempts:0, allDone:false } }];

// RUN ONCE FOR ALL ITEMS — merge poll results back into job list
const collected=$('📦 Collect Video Jobs').first().json;
const polls=$input.all().map(i=>i.json);
const jobs=collected.jobs.map((j,i)=>{
  const p=polls[i]||{};
  const status=p.status||j.status;
  let url=j.clip_url;
  if(status==='completed'){ url=(p.unsigned_urls&&p.unsigned_urls[0]) || ('https://openrouter.ai/api/v1/videos/'+(j.jobId)+'/content?index=0'); }
  return { ...j, status, clip_url:url };
});
const attempts=(collected.attempts||0)+1;
const allDone = jobs.every(j=>j.status==='completed' && j.clip_url);
const anyFailed = jobs.some(j=>['failed','cancelled','expired'].includes(j.status));
return [{ json:{ ...collected, jobs, attempts, allDone, anyFailed, done: allDone || anyFailed || attempts>=20 } }];

// RUN ONCE — build the FFmpeg bash script that assembles all scene clips
const m=$json;
const KEY=$vars.OPENAI_API_KEY;
const OR=$vars.OPENROUTER_API_KEY;
const FONT=$vars.FFMPEG_FONT||'/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf';
const voice=$vars.OPENAI_TTS_VOICE||'onyx';
const dir='/tmp/'+m.job;
const b64=(s)=>Buffer.from(String(s||''),'utf8').toString('base64');
const L=['set -e','export DIR='+dir,'mkdir -p $DIR','cd $DIR'];
const list=[];
(m.jobs||[]).forEach((j,i)=>{
  // download the generated clip (add auth header only for openrouter api urls)
  const auth = j.clip_url.indexOf('openrouter.ai/api')>-1 ? `-H \"Authorization: Bearer ${OR}\"` : '';
  L.push(`curl -sL ${auth} \"${j.clip_url}\" -o clip_${i}.mp4`);
  // TTS narration via OpenAI (base64 payload avoids shell escaping)
  const tts=JSON.stringify({ model:'tts-1-hd', voice:voice, input:j.narration||m.topic });
  L.push(`echo \"${b64(tts)}\" | base64 -d > tts_${i}.json`);
  L.push(`curl -s https://api.openai.com/v1/audio/speech -H \"Authorization: Bearer ${KEY}\" -H \"Content-Type: application/json\" --data @tts_${i}.json -o voice_${i}.mp3`);
  L.push(`echo \"${b64(j.on_screen_text)}\" | base64 -d > cap_${i}.txt`);
  L.push(`D=$(ffprobe -v error -show_entries format=duration -of csv=p=0 voice_${i}.mp3)`);
  const vf=`scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,drawtext=fontfile=${FONT}:textfile=cap_${i}.txt:fontcolor=white:fontsize=64:line_spacing=12:box=1:boxcolor=black@0.55:boxborderw=26:x=(w-text_w)/2:y=h-560`;
  // loop the clip to cover the narration length, overlay voice, burn caption
  L.push(`ffmpeg -y -stream_loop -1 -t $D -i clip_${i}.mp4 -i voice_${i}.mp3 -vf \"${vf}\" -map 0:v -map 1:a -r 30 -c:v libx264 -preset veryfast -pix_fmt yuv420p -c:a aac -b:a 192k -shortest scene_${i}.mp4`);
  list.push(`file 'scene_${i}.mp4'`);
});
L.push(`printf \"${list.join('\\n')}\\n\" > list.txt`);
L.push(`ffmpeg -y -f concat -safe 0 -i list.txt -c copy ${dir}/final.mp4`);
L.push(`echo RENDER_DONE ${dir}/final.mp4`);
return [{ json:{ ...m, outPath:dir+'/final.mp4', ffmpegScript:L.join('\n') } }];

const m=$('🎞️ Build FFmpeg Job').first().json;
const publicUrl=`${$vars.SUPABASE_URL}/storage/v1/object/public/videos/${m.job}.mp4`;
return [{ json:{ chatId:m.chatId, platform:m.platform, title:m.title, description:m.description, tags:m.tags, hashtags:m.hashtags, changes:m.changes, thumbnail_url:m.thumbnail_url, video_url:publicUrl } }];

const m=$('🧮 Finalize').first().json;
const resp=$input.first().json;
const vid=resp.id||(resp.id&&resp.id.videoId)||null;
return [{ json:{ chatId:m.chatId, title:m.title, platform:'youtube', link: vid?('https://youtu.be/'+vid):'', changes:m.changes } }];

const m=$('🧮 Finalize').first().json;
const resp=$input.first().json;
let pubId=null;try{pubId=resp.data.publish_id;}catch(e){}
return [{ json:{ chatId:m.chatId, title:m.title, platform:'tiktok', link: pubId?('TikTok job: '+pubId):'(check TikTok inbox)', changes:m.changes } }];
